#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

banner "Spoke memory onboarding"

stage "Preflight / overlay reachability"
say "Run this on the new spoke, from the dirac-pi-tools checkout root."
if [[ ! -f Makefile ]]; then
  die "Run scripts/spoke-onboard.sh from the dirac-pi-tools repository root; pi-memory join runs make install-spoke there."
fi
if ! command -v pi-memory >/dev/null 2>&1; then
  die "pi-memory is not installed or not on PATH. From this checkout, run make install-bin, then restart this wizard."
fi
command -v make >/dev/null 2>&1 || die "make is required because pi-memory join installs the spoke push timer."
command -v systemctl >/dev/null 2>&1 || die "systemctl is required because pi-memory join installs the spoke push timer."
systemctl --user show-environment >/dev/null 2>&1 || die "A working systemd --user manager is required for pi-memory join to install the push timer."
DETECTED_HOSTNAME=$(hostname -f 2>/dev/null || hostname)
ask HUB_ADDRESS "Hub Nebula/overlay address (hostname or IP, no scheme or port):"
[[ -n "$HUB_ADDRESS" ]] || die "A hub overlay address is required."
[[ "$HUB_ADDRESS" =~ ^[A-Za-z0-9][A-Za-z0-9.:_-]*$ ]] || die "Use only a hostname or IP address, without user@, scheme, port, or whitespace."
ask HUB_PORT "Hub API port [6342]:"
HUB_PORT=${HUB_PORT:-6342}
[[ "$HUB_PORT" =~ ^[0-9]{1,5}$ ]] && (( 10#$HUB_PORT >= 1 && 10#$HUB_PORT <= 65535 )) || die "Hub API port must be an integer from 1 to 65535."
ask SPOKE_NAME "Confirm spoke name / hostname [$DETECTED_HOSTNAME]:"
SPOKE_NAME=${SPOKE_NAME:-$DETECTED_HOSTNAME}
[[ "$SPOKE_NAME" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,254}$ ]] || die "Spoke name must be 1–255 letters, digits, dots, underscores, or hyphens, and start with a letter or digit."
say "Hub: $HUB_ADDRESS:$HUB_PORT · spoke identity: $SPOKE_NAME"
if ping -c 1 -W 3 "$HUB_ADDRESS" >/dev/null 2>&1; then
  say "Overlay ping succeeded."
else
  warn "Ping did not succeed; ICMP may be blocked. Checking SSH reachability next."
fi
if ! ssh -o ConnectTimeout=8 "$HUB_ADDRESS" true; then
  cat >&2 <<EOF_INSTRUCTIONS
Cannot reach the hub over SSH at $HUB_ADDRESS.
If this spoke is not on the Nebula/overlay network, stop here: have the network
administrator enroll it using your deployment's Nebula CA/config procedure,
install its assigned Nebula config/certificate/key, start Nebula, and verify
that it receives an overlay address. Then rerun this wizard. Nebula enrollment
and credential handling are human-only and are not automated here.
If Nebula is already connected, first configure SSH access from this account to
$HUB_ADDRESS and verify that the account has sudo access on the hub.
EOF_INSTRUCTIONS
  exit 1
fi
say "SSH reached the hub. The wizard will not automate Nebula enrollment."

stage "Hub-side preparation"
say "Check the dedicated git account and /home/git/wiki.git; missing or incorrect setup is changed only after confirmation."
HUB_REPO=""
ask HUB_REPO "Absolute path to the dirac-pi-tools checkout on the hub (contains package.json):"
[[ "$HUB_REPO" == /* && "$HUB_REPO" != *$'\n'* ]] || die "Enter the absolute path to the dirac-pi-tools checkout on the hub."
GIT_SHELL=$(ssh "$HUB_ADDRESS" 'command -v git-shell') || die "Could not locate git-shell on the hub. Install git-shell and rerun."
[[ "$GIT_SHELL" =~ ^/[A-Za-z0-9_./-]+$ ]] || die "Hub returned an unexpected git-shell path; inspect it manually: $GIT_SHELL"
GIT_ENTRY=$(ssh "$HUB_ADDRESS" 'getent passwd git || true') || die "Could not inspect the git account on the hub."
if [[ -z "$GIT_ENTRY" ]]; then
  say "The git account is missing; it will be created with git-shell and home /home/git."
  confirm "Create the dedicated git user on the hub using sudo?" || die "Stopped before creating the hub git user."
  ssh -tt "$HUB_ADDRESS" "sudo useradd --create-home --home-dir /home/git --shell '$GIT_SHELL' git" || die "Could not create the hub git account."
  GIT_ENTRY=$(ssh "$HUB_ADDRESS" 'getent passwd git') || die "Could not verify the newly created git account."
fi
IFS=: read -r _ _ _ _ _ GIT_HOME GIT_ACCOUNT_SHELL <<< "$GIT_ENTRY"
[[ "$GIT_HOME" == /home/git ]] || die "The hub git account's home is $GIT_HOME, not /home/git. Resolve this manually before onboarding."
if [[ "$GIT_ACCOUNT_SHELL" != "$GIT_SHELL" ]]; then
  say "The git account uses $GIT_ACCOUNT_SHELL; required shell is $GIT_SHELL."
  confirm "Change the git account shell to git-shell using sudo?" || die "Stopped before changing the hub git account shell."
  ssh -tt "$HUB_ADDRESS" "sudo usermod --shell '$GIT_SHELL' git" || die "Could not set git-shell for the hub git account."
fi
say "Dedicated git account is configured with git-shell."
REPO_STATE=$(ssh "$HUB_ADDRESS" 'if [ ! -e /home/git/wiki.git ]; then printf missing; elif [ "$(git -C /home/git/wiki.git rev-parse --is-bare-repository 2>/dev/null)" = true ]; then printf bare; else printf invalid; fi') || die "Could not inspect /home/git/wiki.git on the hub."
if [[ "$REPO_STATE" == missing ]]; then
  say "The canonical bare repository is missing."
  confirm "Create /home/git/wiki.git as a bare repository using sudo?" || die "Stopped before creating the hub wiki repository."
  ssh -tt "$HUB_ADDRESS" 'sudo -u git git init --bare /home/git/wiki.git' || die "Could not create /home/git/wiki.git."
  REPO_STATE=$(ssh "$HUB_ADDRESS" 'git -C /home/git/wiki.git rev-parse --is-bare-repository 2>/dev/null') || die "Could not verify the newly created /home/git/wiki.git."
  [[ "$REPO_STATE" == true ]] || die "/home/git/wiki.git was created but is not a valid bare repository. Inspect it manually."
  REPO_OWNER=$(ssh "$HUB_ADDRESS" 'stat -c %U /home/git/wiki.git') || die "Could not inspect ownership of /home/git/wiki.git."
  [[ "$REPO_OWNER" == git ]] || die "/home/git/wiki.git was created but is owned by $REPO_OWNER, not git. Resolve ownership manually."
elif [[ "$REPO_STATE" == bare ]]; then
  REPO_OWNER=$(ssh "$HUB_ADDRESS" 'stat -c %U /home/git/wiki.git') || die "Could not inspect ownership of /home/git/wiki.git."
  [[ "$REPO_OWNER" == git ]] || die "/home/git/wiki.git is bare but owned by $REPO_OWNER, not git. Resolve ownership manually before onboarding."
  say "Canonical bare repository exists and is owned by git."
else
  die "/home/git/wiki.git exists but is not a valid bare repository. Inspect it manually; the wizard will not replace it."
fi

say "Minting a one-spoke token on the hub. Its output is captured silently and is never displayed or saved by this wizard."
confirm "Mint a new hub token for spoke '$SPOKE_NAME'?" || die "Stopped before minting a hub token."
HUB_REPO_B64=$(printf '%s' "$HUB_REPO" | base64 | tr -d '\r\n')
TOKEN_JSON=$(ssh "$HUB_ADDRESS" "bash -c 'repo=\$(printf \"%s\" \"\$1\" | base64 -d); cd -- \"\$repo\" && npm run --silent memory -- hub-token add \"\$2\"' _ '$HUB_REPO_B64' '$SPOKE_NAME'") || die "Hub token creation failed. Check the repo path and hub CLI output, then rerun; no token was captured."
TOKEN_CREATED=1
JOIN_STARTED=0
JOIN_SUCCEEDED=0
trap cleanup_unjoined_token EXIT
if ! TOKEN=$(printf '%s' "$TOKEN_JSON" | node -e 'let s="";process.stdin.setEncoding("utf8");process.stdin.on("data",x=>s+=x);process.stdin.on("end",()=>{try{const o=JSON.parse(s);if(!o.ok||typeof o.token!=="string"||!o.token||/\s/.test(o.token)||o.spoke!==process.argv[1])process.exitCode=1;else process.stdout.write(o.token)}catch{process.exitCode=1}})' "$SPOKE_NAME"); then
  unset TOKEN_JSON
  die "Hub token command returned unexpected output; the token was not displayed. Inspect hub token state before retrying."
fi
unset TOKEN_JSON
say "Hub token created and held in memory for the join stage."

stage "Enroll spoke SSH key"
SSH_DIR="$HOME/.ssh"
PRIVATE_KEY="$SSH_DIR/id_ed25519"
PUBLIC_KEY="$PRIVATE_KEY.pub"
if [[ -L "$SSH_DIR" ]]; then die "Refusing to use a symlink for $SSH_DIR."; fi
if [[ -L "$PRIVATE_KEY" || -L "$PUBLIC_KEY" ]]; then die "Refusing to use symlinked id_ed25519 key files."; fi
if [[ ! -d "$SSH_DIR" ]]; then
  confirm "Create $SSH_DIR with private permissions?" || die "Stopped before creating the local SSH directory."
  mkdir -m 700 -p "$SSH_DIR"
fi
if [[ ! -e "$PRIVATE_KEY" && ! -e "$PUBLIC_KEY" ]]; then
  say "No default ed25519 keypair exists. A key will be generated without a passphrase; no private key will leave this spoke."
  confirm "Generate $PRIVATE_KEY now?" || die "Stopped before generating the spoke SSH key."
  ssh-keygen -q -t ed25519 -C "$SPOKE_NAME" -f "$PRIVATE_KEY" -N "" || die "Could not generate the ed25519 keypair."
elif [[ ! -f "$PRIVATE_KEY" || ! -f "$PUBLIC_KEY" ]]; then
  die "An incomplete id_ed25519 keypair exists. Restore the matching public/private key files manually; the wizard will not overwrite either."
fi
chmod 700 "$SSH_DIR"
[[ -f "$PRIVATE_KEY" && ! -L "$PRIVATE_KEY" && -f "$PUBLIC_KEY" && ! -L "$PUBLIC_KEY" ]] || die "Expected regular id_ed25519 key files in $SSH_DIR."
[[ $(wc -l < "$PUBLIC_KEY") -eq 1 ]] || die "The public key file must contain exactly one key line."
ssh-keygen -lf "$PUBLIC_KEY" >/dev/null 2>&1 || die "The public key file is not a valid SSH key."
KEY_FIELDS=$(awk 'NF >= 2 { print $1, $2; exit }' "$PUBLIC_KEY")
[[ "$KEY_FIELDS" == ssh-ed25519\ * ]] || die "The default public key is not ed25519. Resolve it manually; the wizard will not print or replace keys."
PUBKEY_LINE="$KEY_FIELDS $SPOKE_NAME"
PUBKEY_B64=$(printf '%s' "$PUBKEY_LINE" | base64 | tr -d '\r\n')
say "Enrolling the public key on the hub (comment: $SPOKE_NAME). Private key remains on this spoke and is never printed."
confirm "Append this spoke's public key to /home/git/.ssh/authorized_keys on the hub using sudo?" || die "Stopped before enrolling the spoke SSH key."
REMOTE_KEY_SCRIPT='set -euo pipefail; key=$(printf "%s" "$1" | base64 -d); [[ ! -L /home/git/.ssh ]] || exit 1; install -d -o git -g git -m 700 /home/git/.ssh; [[ ! -L /home/git/.ssh/authorized_keys ]] || exit 1; [[ ! -e /home/git/.ssh/authorized_keys || -f /home/git/.ssh/authorized_keys ]] || exit 1; touch /home/git/.ssh/authorized_keys; chown git:git /home/git/.ssh/authorized_keys; chmod 600 /home/git/.ssh/authorized_keys; if grep -Fxq -- "$key" /home/git/.ssh/authorized_keys; then printf "Public key already enrolled.\\n"; else printf "%s\\n" "$key" >> /home/git/.ssh/authorized_keys; printf "Public key enrolled.\\n"; fi'
printf -v REMOTE_KEY_COMMAND 'sudo bash -c %q -- %q' "$REMOTE_KEY_SCRIPT" "$PUBKEY_B64"
ssh -tt "$HUB_ADDRESS" "$REMOTE_KEY_COMMAND" || die "Could not enroll the public key on the hub. The token remains in memory; resolve access and rerun only after checking whether the key was appended."
unset PUBKEY_B64 REMOTE_KEY_SCRIPT REMOTE_KEY_COMMAND PUBKEY_LINE KEY_FIELDS
say "SSH key enrollment completed before the first wiki clone."

stage "Join the memory hub"
say "pi-memory join writes hub.json with mode 0600, updates the managed Host memory-hub block, clones the wiki, and installs the spoke push timer."
confirm "Run pi-memory join against $HUB_ADDRESS:$HUB_PORT for '$SPOKE_NAME'?" || die "Stopped before writing spoke hub configuration; the unjoined token will be revoked automatically."
JOIN_STARTED=1
pi-memory join "$HUB_ADDRESS" --port "$HUB_PORT" --token "$TOKEN" || die "pi-memory join failed. The wizard will retain the token only if join wrote it to hub.json; inspect state before retrying."
JOIN_SUCCEEDED=1
unset TOKEN

stage "Verify the spoke"
say "Check authenticated hub status, push this spoke's local Pi sessions, and verify SSH Git access."
pi-memory join --status || die "Hub status verification failed."
confirm "Run pi-memory push now? This sends local Pi session files to the hub." || die "Stopped before the verification push. Run pi-memory push after reviewing what will be sent."
pi-memory push || die "The test push failed. Check the spoke session files and hub ingest service."
git ls-remote git@memory-hub:wiki.git || die "Git authentication to the hub wiki failed."
say "Hub API status, a test push, and SSH Git access all succeeded."

finish
}

die() {
  printf '\n%sERROR:%s %s\n' "$YELLOW" "$RESET" "$1" >&2
  exit 1
}

cleanup_unjoined_token() {
  local exit_status=$? revoke=1 config_file
  trap - EXIT
  if [[ "${TOKEN_CREATED:-0}" == 1 && "${JOIN_SUCCEEDED:-0}" != 1 ]]; then
    if [[ "${JOIN_STARTED:-0}" == 1 && -n "${TOKEN:-}" ]]; then
      config_file="${PI_CODING_AGENT_DIR:-$HOME/.pi/agent}/memory/hub.json"
      if [[ -f "$config_file" ]] && node -e 'try { process.exit(JSON.parse(require("node:fs").readFileSync(process.argv[1], "utf8")).token === process.argv[2] ? 0 : 1) } catch { process.exit(1) }' "$config_file" "$TOKEN"; then
        revoke=0
        warn "Join wrote hub.json before failing; the token was retained. Inspect the partial setup before retrying."
      fi
    fi
    if (( revoke )); then
      if ssh "$HUB_ADDRESS" "bash -c 'repo=\$(printf \"%s\" \"\$1\" | base64 -d); cd -- \"\$repo\" && npm run --silent memory -- hub-token revoke \"\$2\"' _ '$HUB_REPO_B64' '$SPOKE_NAME'" >/dev/null 2>&1; then
        say "The unjoined spoke token was revoked on the hub."
      else
        warn "Could not automatically revoke the unjoined token; on the hub run: npm run memory -- hub-token revoke $SPOKE_NAME"
      fi
    fi
  fi
  exit "$exit_status"
}

run_wizard "$@"; exit
